const body = $input.first().json;
const website = (body.website || '').trim();
if (!website) throw new Error('website is required');
const apify_token = (body.apify_token || process.env.APIFY_API_TOKEN || '').trim();
if (!apify_token) throw new Error('apify_token is required');
const max_pages = parseInt(body.max_pages || '5', 10);
const base = website.replace(/\/+$/, '');
return [{ json: { website, vendor_name: body.vendor_name || '', apify_token, max_pages, base, admin_url: body.admin_url || '' } }];

const website = $('Validate Input').first().json.website;
const inputName = $('Validate Input').first().json.vendor_name || '';
const results = $input.first().json;
const items = Array.isArray(results) ? results : [results];

const TAGLINE_SUFFIXES = new Set(['analytics','automation','dashboard','insights','intelligence','management','monitoring','platform','reporting','software','solution','solutions','tracking']);
function isTagline(text) {
  const lower = (text||'').toLowerCase();
  if (TAGLINE_SUFFIXES.has(lower.split(/\s+/).pop())) return true;
  if (/\bai[- ]powered\b|\b\w+-powered\b|\bpowered by\b/.test(lower)) return true;
  if (/\b\d{4}\b/.test(lower)) return true;
  return false;
}
function cleanCandidate(raw) {
  let s = (raw||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  if (!s) return '';
  for (const sep of [' | ',' - ',' – ',' — ',': ']) {
    if (s.includes(sep)) { for (const p of s.split(sep)) { const c=cleanCandidate(p); if(c) return c; } }
  }
  if (isTagline(s)) return '';
  if (s.split(/\s+/).length > 5) return '';
  if (s.length > 40) return '';
  return s;
}
function domainStem(url) {
  try {
    const base = new URL(url).hostname.replace(/^www\./,'').split('.')[0].toLowerCase();
    for (const p of ['get','try','use','my','the']) {
      if (base.startsWith(p) && base.length-p.length >= 4)
        return base.slice(p.length).charAt(0).toUpperCase()+base.slice(p.length+1);
    }
    return base.charAt(0).toUpperCase()+base.slice(1);
  } catch { return ''; }
}

// Build pages array — tag pricing pages for visibility
const pages = items.map(item => {
  const pageUrl = item.url || item.loadedUrl || '';
  const isPricing = /\/pricing|\/plans|\/pricing-plans/i.test(pageUrl);
  return {
    url: pageUrl,
    title: item.title || item.metadata?.title || '',
    text: (item.text || item.markdown || item.content || '').slice(0, 5000),
    is_pricing_page: isPricing
  };
}).filter(p => p.url);

// Find best name from all pages (prefer homepage)
let name = '';
for (const page of pages) {
  const c = cleanCandidate(page.title);
  if (c) { name = c; break; }
}
if (!name) name = cleanCandidate(inputName) || domainStem(website);

// Separate homepage and pricing pages for combined text
const homepagePages = pages.filter(p => !p.is_pricing_page);
const pricingPages = pages.filter(p => p.is_pricing_page);
const homepageText = homepagePages.map(p => p.text).join(' ');
const pricingText = pricingPages.map(p => p.text).join('\n\n[PRICING PAGE]\n');
const pricing_page_found = pricingText.length > 100;

const allText = homepageText + (pricing_page_found ? '\n\n[PRICING PAGE]\n' + pricingText : '');
const word_count = allText ? allText.split(/\s+/).length : 0;

return [{ json: { website, name, word_count, text: allText.slice(0, 12000), pages, tier_used: 'tier3_wcc', ok: true, pricing_page_found, pages_fetched: pages.length } }];
